// 주간 보고 집계
const 목표건수 = 100; // ← 캠페인 목표에 맞게 수정
const rows = items.map(i => i.json);

const done = (s) => /예약완료|발행완료|완료/.test(String(s || ''));
const fail = (s) => /실패/.test(String(s || ''));

const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const parseDate = (r) => {
  const v = r['발행예정일'] || r['기록시각'] || '';
  const d = new Date(String(v).replace(/\./g, '-'));
  return isNaN(d) ? null : d;
};

let totalDone = 0, totalFail = 0, weekDone = 0;
const byCompany = {};
for (const r of rows) {
  const s = r['상태'] || r['발행상태'] || '';
  if (done(s)) totalDone++;
  if (fail(s)) totalFail++;
  const d = parseDate(r);
  if (d && d >= weekAgo && d <= now && done(s)) {
    weekDone++;
    const c = r['업체명'] || '기타';
    byCompany[c] = (byCompany[c] || 0) + 1;
  }
}

const pad = (n) => String(n).padStart(2, '0');
const ymd = `${String(now.getFullYear()).slice(2)}.${pad(now.getMonth() + 1)}.${pad(now.getDate())}`;
const breakdown = Object.entries(byCompany)
  .sort((a, b) => b[1] - a[1])
  .map(([c, n]) => `  · ${c}: ${n}개`).join('\n') || '  · (금주 발행 없음)';

let msg = `안녕하세요. 작업 중간 보고 드립니다.\n`;
msg += `소식글 작성 ${totalDone}/${목표건수}\n`;
msg += `${ymd} / 금주 ${weekDone}개 완료\n\n`;
msg += `[업체별 금주 발행]\n${breakdown}`;
if (totalFail > 0) msg += `\n\n⚠️ 발행 실패 누적: ${totalFail}건 (시트 확인 필요)`;

return [{ json: { message: msg, totalDone, totalFail, weekDone, 목표건수 } }];
